void check(bool v,const char* message){if(!v)throw std::runtime_error(message);}
std::vector<std::uint8_t> fixture(unsigned depth,const ase::Bytes& pixel){ase::Writer chunks,layer;layer.u16(3);layer.u16(0);layer.u16(0);layer.zero(4);layer.u16(0);layer.u8(255);layer.zero(3);layer.str(U"fixture");chunks.chunk(0x2004,layer);unsigned n=2;if(depth==8){ase::Writer p;p.u32(2);p.u32(1);p.u32(1);p.zero(8);p.u16(0);p.u32(0xff563412);chunks.chunk(0x2019,p);n++;}ase::Writer cel;cel.u16(0);cel.u16(65535);cel.u16(0);cel.u8(255);cel.u16(0);cel.u16(0);cel.zero(5);cel.u16(1);cel.u16(1);cel.raw(pixel);chunks.chunk(0x2005,cel);ase::Writer out;out.u32(unsigned(144+chunks.b.size()));out.u16(0xa5e0);out.u16(1);out.u16(2);out.u16(1);out.u16(depth);out.u32(3);out.u16(100);out.zero(108);out.u32(unsigned(16+chunks.b.size()));out.u16(0xf1fa);out.u16(n);out.u16(100);out.zero(6);out.raw(chunks.b);return out.b;}
void specialLayerExport(){
 for(bool free:{false,true})for(bool masked:{false,true}){
  Document seed(8,6);seed.beginStroke({1,1},0xff123456);seed.commitStroke();
  if(free){seed.createFreeTileLayer(U"Free ASE");SelectionClipboard tile;tile.width=tile.height=2;tile.pixels={0xff112233,0x80445566,0,0xffabcdef};seed.pasteFreeTilePixels(tile,{2,1});seed.setFreeTilePaintMode(false);}else seed.convertLayerToTilemap(2,2,U"Grid ASE");
  seed.addFrame(true);auto state=seed.timeline().state();const auto owner=seed.cel().id;auto alias=seed.cel();alias.id="ase-special-alias";alias.frameId="ase-special-frame";alias.linkedCelId=owner;alias.surface.reset();alias.tilemap.reset();alias.freeTiles.reset();state.frames.push_back({alias.frameId,73});state.cels.push_back(alias);for(const auto& layer:state.layers)if(layer.id!=alias.layerId){auto extra=*seed.timeline().findCel(layer.id,seed.frame().id);extra.id="ase-extra-"+layer.id;extra.frameId=alias.frameId;state.cels.push_back(extra);}
  if(masked){timeline::MaskSlot mask;mask.ownerId=seed.layer().id;mask.frameId=seed.frame().id;mask.mask.id="ase-special-mask";mask.mask.surface.width=8;mask.mask.surface.height=6;mask.mask.surface.pixels.assign(48,0xffffffff);mask.mask.surface.pixels[10]=0xff000000;state.masks.push_back(mask);}
  auto d=Document::fromImported(8,6,state,seed.palette(),"ase-special",U"Special",std::make_shared<const std::vector<std::uint8_t>>());const auto revision=d.contentRevision(),history=d.historySize();const auto pixels=d.canvasPixels();
  for(int scale:{100,200}){auto opened=documentFromAseprite(decodeAseprite(encodeAseprite(d,scale)));check(opened.timeline().state().frames.size()==state.frames.size(),"special ASE retains all frames");check(opened.timeline().state().layers.size()==(masked?1:state.layers.size()),"special ASE preserves layers unless effects require composite");for(std::size_t i=0;i<state.frames.size();++i){auto expected=compositeNormalRegion(d.timeline(),state.frames[i].id,{0,0,8,6});auto actual=compositeNormalRegion(opened.timeline(),opened.timeline().state().frames[i].id,{0,0,8*scale/100,6*scale/100});for(int y=0;y<6*scale/100;++y)for(int x=0;x<8*scale/100;++x)check(actual[y*(8*scale/100)+x]==expected[(y*100/scale)*8+x*100/scale],"special ASE scaled appearance roundtrip");}if(!masked)check(std::any_of(opened.timeline().state().cels.begin(),opened.timeline().state().cels.end(),[](const auto& c){return c.linkedCelId.has_value();}),"special ASE retains backward frame link");}
  check(d.contentRevision()==revision&&d.historySize()==history&&d.canvasPixels()==pixels,"special ASE export leaves authority unchanged");
 }
}
void effectCompositeExport(){
 for(int effect=0;effect<4;++effect)for(bool enabled:{false,true}){
  Document seed(6,4);seed.beginStroke({1,1},0xff123456);seed.commitStroke();seed.addLayer();seed.beginStroke({2,1},0xffabcdef);seed.commitStroke();seed.addFrame(true);auto state=seed.timeline().state();timeline::Group group;group.id="ase-effects-group";group.name=U"Effects";state.groups.push_back(group);state.layers.front().groupId=group.id;timeline::ColorOverlayStyle style;style.enabled=enabled;style.overlayEnabled=true;style.color=0xff113355;
  if(effect==0)state.layers.front().clippingMask=enabled;if(effect==1)state.groups.front().clippingMask=enabled;if(effect==2)state.layers.front().layerStyles=style;if(effect==3)state.groups.front().layerStyles=style;
  auto d=Document::fromImported(6,4,state,seed.palette(),"ase-effects",U"Effects",std::make_shared<const std::vector<std::uint8_t>>());const auto revision=d.contentRevision(),history=d.historySize();const auto issues=asepriteSaveIssues(d);check(asepriteNeedsComposite(d.timeline().state())==enabled,"ASE effect composite gate");check((std::find(issues.begin(),issues.end(),"effects")!=issues.end())==enabled,"ASE effect loss warning gate");auto opened=documentFromAseprite(decodeAseprite(encodeAseprite(d)));check(opened.timeline().state().layers.size()==(enabled?1:2),"ASE effect flattening boundary");for(std::size_t i=0;i<state.frames.size();++i)check(compositeNormalRegion(d.timeline(),state.frames[i].id,{0,0,6,4})==compositeNormalRegion(opened.timeline(),opened.timeline().state().frames[i].id,{0,0,6,4}),"ASE effect composite frame appearance");check(d.contentRevision()==revision&&d.historySize()==history,"ASE effect export authority unchanged");
 }
}
void sparseTimelineExport(){
 Document seed(3,2);seed.beginStroke({1,0},0xff123456);seed.commitStroke();seed.addLayer();for(int i=1;i<5;++i)seed.addFrame();
 auto imported=decodeAseprite(encodeAseprite(seed));auto& state=imported.timeline;const auto layer=state.layers.front().id,other=state.layers.back().id;
 auto source=*std::find_if(state.cels.begin(),state.cels.end(),[&](const auto& c){return c.layerId==layer;});source.id="sparse-source";source.frameId=state.frames[1].id;source.opacity=128./255;source.zIndex=-2;source.surface->pixels.assign(source.surface->pixels.size(),0xff123456);
 auto forward=source;forward.id="sparse-forward";forward.frameId=state.frames[0].id;forward.linkedCelId=source.id;forward.surface.reset();auto backward=forward;backward.id="sparse-backward";backward.frameId=state.frames[3].id;
 auto transparent=source;transparent.id="sparse-transparent";transparent.layerId=other;transparent.frameId=state.frames[4].id;transparent.opacity=1;transparent.zIndex=0;transparent.surface->pixels.assign(transparent.surface->pixels.size(),0);
 state.cels={forward,source,backward,transparent};auto d=documentFromAseprite(std::move(imported));const auto revision=d.contentRevision(),history=d.historySize();
 auto bytes=encodeAseprite(d);ase::Reader file(bytes);file.skip(128);const unsigned expected[]={1,1,0,1,1};
 for(unsigned fi=0;fi<5;++fi){auto begin=file.p;auto size=file.u32();check(file.u16()==0xf1fa,"sparse frame magic");auto count=file.u16();file.skip(4);auto extended=file.u32();if(count==65535)count=extended;unsigned cels=0;
  for(unsigned n=0;n<count;++n){auto start=file.p;auto length=file.u32();auto type=file.u16();if(type==0x2005){++cels;file.u16();file.skip(4);auto opacity=file.u8();auto kind=file.u16();auto z=file.s16();file.skip(5);check(opacity==(fi==4?255:128)&&z==(fi==4?0:-2),"sparse cel opacity and z");check(kind==(fi==3?1:2),"forward links materialized and backward links retained");if(kind==1)check(file.u16()==1,"sparse backward source frame");}file.p=start+length;}
  check(cels==expected[fi],"missing slots emit no cel chunk; explicit transparent cel retained");check(file.p==begin+size,"sparse frame chunk length");
 }
 auto decoded=decodeAseprite(bytes);check(decoded.timeline.cels.size()==4,"sparse import preserves missing slots");auto reopened=documentFromAseprite(std::move(decoded));check(reopened.timeline().state().cels.size()==4,"opening does not materialize empty slots");
 for(unsigned fi=0;fi<5;++fi)check(compositeNormalRegion(d.timeline(),d.timeline().state().frames[fi].id,{0,0,3,2})==compositeNormalRegion(reopened.timeline(),reopened.timeline().state().frames[fi].id,{0,0,3,2}),"sparse frame appearance roundtrip");
 auto emptyImport=decodeAseprite(bytes);emptyImport.timeline.cels.clear();auto empty=documentFromAseprite(std::move(emptyImport));check(empty.canvasPixels()==std::vector<timeline::Pixel>(6,0),"empty active slot canvas");auto emptyRound=decodeAseprite(encodeAseprite(empty));check(emptyRound.timeline.cels.empty()&&emptyRound.timeline.frames.size()==5,"fully empty animation preserves frames without cels");
 auto compositeImport=decodeAseprite(bytes);compositeImport.timeline.layers.front().clippingMask=true;auto composite=documentFromAseprite(std::move(compositeImport));auto compositeRound=documentFromAseprite(decodeAseprite(encodeAseprite(composite)));check(compositeRound.timeline().state().cels.size()==5,"composite export includes every frame despite sparse source");for(unsigned fi=0;fi<5;++fi)check(compositeNormalRegion(composite.timeline(),composite.timeline().state().frames[fi].id,{0,0,3,2})==compositeNormalRegion(compositeRound.timeline(),compositeRound.timeline().state().frames[fi].id,{0,0,3,2}),"sparse composite appearance");
 auto second=decodeAseprite(encodeAseprite(reopened));check(second.timeline.cels.size()==4,"sparse save reopen remains sparse");check(d.contentRevision()==revision&&d.historySize()==history&&d.timeline().state().cels.size()==4,"sparse export leaves authority unchanged");
}
int main(){try{sparseTimelineExport();effectCompositeExport();specialLayerExport();for(auto depth:{32u,16u,8u}){auto bytes=fixture(depth,depth==32?ase::Bytes{0x12,0x34,0x56,0xff}:depth==16?ase::Bytes{0x40,0x80}:ase::Bytes{1});auto imported=decodeAseprite(bytes);check(imported.palette.entries.size()==1&&imported.palette.entries[0].name==U"1","legacy imported color name");check(imported.timeline.cels[0].surface->offsetX==-1,"signed offset");auto color=imported.timeline.cels[0].surface->pixels[0];check(color==(depth==16?0x80404040u:0xff563412u),"depth pixel conversion");}
 Document d(3,1);d.beginStroke({0,0},0xff123456);d.commitStroke();d.setFrameDuration(43);d.addFrame();d.beginStroke({1,0},0x80563412);d.commitStroke();d.setFrameDuration(217);auto before=d.contentRevision();auto encoded=encodeAseprite(d);auto value=decodeAseprite(encoded);check(value.timeline.frames.size()==2&&value.timeline.frames[0].duration==43&&value.timeline.frames[1].duration==217,"frame durations");auto reopened=documentFromAseprite(std::move(value));check(!reopened.dirty()&&reopened.sourceFilePath().empty(),"non native import identity");for(std::size_t f=0;f<2;f++)check(compositeNormalRegion(d.timeline(),d.timeline().state().frames[f].id,{0,0,3,1})==compositeNormalRegion(reopened.timeline(),reopened.timeline().state().frames[f].id,{0,0,3,1}),"roundtrip frame pixels");check(before==d.contentRevision(),"export mutation");
 auto linked=decodeAseprite(encoded);auto& a=linked.timeline.cels[0];auto& b=linked.timeline.cels[1];b.surface.reset();b.linkedCelId=a.id;b.opacity=a.opacity;b.zIndex=a.zIndex;timeline::Group g;g.id="group";g.name=U"组";linked.timeline.groups.push_back(g);linked.timeline.layers[0].groupId=g.id;timeline::LoopSection tag;tag.id="tag";tag.name=U"往返";tag.startFrameId=linked.timeline.frames[0].id;tag.endFrameId=linked.timeline.frames[1].id;tag.direction="ping-pong-reverse";tag.repeatCount=3;linked.timeline.loopSections.push_back(tag);auto linkedDoc=documentFromAseprite(std::move(linked));auto round=decodeAseprite(encodeAseprite(linkedDoc));check(round.timeline.groups.size()==1&&round.timeline.layers[0].groupId==round.timeline.groups[0].id,"group hierarchy");check(round.timeline.cels[1].linkedCelId.has_value(),"backward cel link");check(round.timeline.loopSections.size()==1&&round.timeline.loopSections[0].direction=="ping-pong-reverse"&&round.timeline.loopSections[0].repeatCount==3,"tag semantics");
 auto masked=decodeAseprite(encoded);timeline::MaskSlot mask;mask.ownerId=masked.timeline.layers[0].id;mask.frameId=masked.timeline.frames[0].id;mask.mask.id="mask";mask.mask.surface.width=3;mask.mask.surface.height=1;mask.mask.surface.pixels={0xffffffff,0xff000000,0xff000000};masked.timeline.masks.push_back(mask);auto maskedDoc=documentFromAseprite(std::move(masked));auto baked=documentFromAseprite(decodeAseprite(encodeAseprite(maskedDoc)));check(baked.timeline().state().layers.size()==1&&baked.timeline().state().masks.empty(),"mask export composite");check(compositeNormalRegion(maskedDoc.timeline(),maskedDoc.frame().id,{0,0,3,1})==compositeNormalRegion(baked.timeline(),baked.frame().id,{0,0,3,1}),"mask appearance");bool rejected=false;try{encoded.pop_back();decodeAseprite(encoded);}catch(const std::exception&){rejected=true;}check(rejected,"truncated rejection");std::cout<<"ASE IO checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}